public PoolService(PoolRepository pools, PoolMemberRepository members, PersonRepository people,
        CrewRepository crews, CrewMemberRepository crewMembers, SheetService sheets, Audit audit) {
    this.pools = pools;
    this.members = members;
    this.people = people;
    this.crews = crews;
    this.crewMembers = crewMembers;
    this.sheets = sheets;
    this.audit = audit;
}

/** The sheet's pools, in the order they were added, each with its members. */
public List<PoolWithMembers> list(String sheetId) {
    List<Pool> list = pools.findBySheetIdOrderByIdAsc(sheetId);
    Map<Long, List<PoolMember>> byPool = members
            .findByPoolIdInOrderByIdAsc(list.stream().map(Pool::getId).toList()).stream()
            .collect(Collectors.groupingBy(PoolMember::getPoolId));
    return list.stream().map(p -> new PoolWithMembers(p, byPool.getOrDefault(p.getId(), List.of()))).toList();
}

/** The sheet's crews as pools, in the order they were added: each the lead and the members at equal
 *  shares, 100.00 split as patrons' shares are (each rounded half to even), the remainder on the lead. */
public List<CrewPool> crewPools(String sheetId) {
    List<Crew> list = crews.findBySheetIdOrderByIdAsc(sheetId);
    Map<Long, List<CrewMember>> byCrew = crewMembers
            .findByCrewIdInOrderByIdAsc(list.stream().map(Crew::getId).toList()).stream()
            .collect(Collectors.groupingBy(CrewMember::getCrewId));
    return list.stream().map(crew -> {
        List<Long> ids = new ArrayList<>();
        ids.add(crew.getLeadId());
        byCrew.getOrDefault(crew.getId(), List.of()).forEach(m -> ids.add(m.getPersonId()));
        return new CrewPool(crew, ids, equalShares(ids.size()));
    }).toList();
}

/** 100.00 split equally over this many, each rounded half to even, the remainder on the first. */
private static List<BigDecimal> equalShares(int count) {
    BigDecimal each = HUNDRED.divide(BigDecimal.valueOf(count), 2, RoundingMode.HALF_EVEN);
    List<BigDecimal> shares = new ArrayList<>();
    for (int i = 0; i < count; i++) {
        shares.add(each);
    }
    shares.set(0, each.add(HUNDRED.subtract(each.multiply(BigDecimal.valueOf(count)))));
    return shares;
}

/** Add a pool, its name trimmed. Refused when the name is blank or already a pool's or a crew's on the sheet.
 *  The sheet is held locked so the same name added at the same moment is checked against itself. */
@Transactional
public PoolWithMembers add(String sheetId, String user, String name) {
    String key = name == null ? "" : name.trim();
    if (key.isEmpty()) {
        throw new PoolRefusedException("A pool needs a name");
    }
    sheets.lock(sheetId);
    if (pools.existsBySheetIdAndName(sheetId, key)) {
        throw new PoolRefusedException("The pool " + key + " is on the sheet already");
    }
    if (crews.existsBySheetIdAndName(sheetId, key)) {
        throw new PoolRefusedException("The crew " + key + " is a pool on the sheet already");
    }
    Pool saved = pools.saveAndFlush(new Pool(sheetId, key));
    audit.recordOnCommit("POOL_ADDED sheet=" + sheetId + " by=" + user + " name=" + key);
    return new PoolWithMembers(saved, List.of());
}

/** Add a member to a pool with a share percent: more than 0.00 and at most 100.00, with up to two
 *  decimals, and an optional from-date and to-date, both included. The member is a person of the
 *  sheet, or another pool of the sheet (memberPoolId). Refused for such a share, a to-date before
 *  the from-date, a person already in the pool, a pool that is a member of a pool
 *  already, a pool that would contain itself through any chain, or a chain of pools more than
 *  three deep. */
    }
}

/** A pool as the screen shows it, with its members in the order they were added. A crew shows as a
 *  pool too (crew true), its id the crew's negated so it is told apart from the sheet's pools; its
 *  members are its lead's and its members' and none is added through the pool. */
public record PoolView(Long id, String name, List<PoolMemberView> members, boolean crew) {
    static PoolView of(PoolService.PoolWithMembers pool) {
        return new PoolView(pool.pool().getId(), pool.pool().getName(),
                pool.members().stream().map(PoolMemberView::of).toList(), false);
    }

    static PoolView of(PoolService.CrewPool pool) {
        List<PoolMemberView> members = new ArrayList<>();
        for (int i = 0; i < pool.personIds().size(); i++) {
            members.add(new PoolMemberView(pool.personIds().get(i), null, pool.shares().get(i).toPlainString(),
                    null, null));
        }
        return new PoolView(-pool.crew().getId(), pool.crew().getName(), members, true);
    }
}

/** A pool: its name, trimmed as it is added. */
public record PoolRequest(@NotBlank @Size(max = 255) String name) {
}

